"""Kconfig environment setup — aligned with usr_config.py mconf_set_env."""

from __future__ import annotations

import os

from kconfig.paths import build_output_path, config_file_path, target_to_config_basename


def apply_kconfig_env(
    sdk_root: str,
    chip: str,
    core: str,
    target: str,
) -> dict[str, str]:
    """Set os.environ for kconfiglib and return paths used."""
    conf = config_file_path(sdk_root, chip, core, target)
    output = build_output_path(sdk_root, chip, core, target)
    os.makedirs(output, exist_ok=True)

    config_header = (
        "# Generated by Kconfig Tool.\n"
        "# Note: !!!This file can not be modify manually!!!\n"
    )
    autoheader_header = (
        "/* Copyright (c) HiSilicon (Shanghai) Technologies Co., Ltd. "
        "2022-2022. All rights reserved. */\n"
    )

    os.environ["MENUCONFIG_STYLE"] = "default selection=fg:white,bg:blue"
    os.environ["KCONFIG_CONFIG"] = conf
    os.environ["KCONFIG_CONFIG_HEADER"] = config_header
    os.environ["KCONFIG_AUTOHEADER"] = os.path.join(output, "mconfig.h")
    os.environ["KCONFIG_AUTOHEADER_HEADER"] = autoheader_header
    os.environ["CONFIG_"] = "CONFIG_"

    return {
        "config_path": conf,
        "output_path": output,
        "kconfig_root": os.path.join(sdk_root, "config.in"),
    }


def default_menus_export_path(sdk_root: str, target: str) -> str:
    base = target_to_config_basename(target)
    here = os.path.dirname(os.path.abspath(__file__))
    export_dir = os.path.join(here, "export")
    os.makedirs(export_dir, exist_ok=True)
    return os.path.join(export_dir, f"{base}_menus.json")
